<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=current_user($pdo);
$sources=$pdo->query("SELECT s.public_id,s.title,s.domain,s.canonical_url,s.status,COUNT(a.id) annotation_count,COUNT(DISTINCT a.user_id) contributor_count,MAX(a.published_at) last_activity FROM sources s JOIN annotations a ON a.source_id=s.id AND a.visibility='public' AND a.status='published' GROUP BY s.id ORDER BY last_activity DESC LIMIT 30")->fetchAll();
$annotations=$pdo->query("SELECT a.public_id,a.text_commentary,a.audio_commentary_path,a.published_at,u.username,u.display_name,s.public_id source_public_id,s.title,s.canonical_url,c.selected_text,at.status transcript_status,COALESCE(at.edited_text,at.raw_text) transcript_text FROM annotations a JOIN users u ON u.id=a.user_id JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id LEFT JOIN annotation_transcripts at ON at.annotation_id=a.id WHERE a.visibility='public' AND a.status='published' ORDER BY a.published_at DESC LIMIT 20")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explore · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><?php if($u):?><a href="/home.php">Home</a><?php endif?><a href="/explore.php">Explore</a><a href="/search.php">Search</a><?php if($u):?><a href="/saved.php">Saved</a><a href="/notifications.php">Notifications</a><a href="/settings.php">Settings</a><?php else:?><a href="/login.php">Log in</a><a href="/register.php">Sign up</a><?php endif?></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">EXPLORE</span><h1>What the web is talking about</h1><p>Browse active sources and the annotations accumulating around them.</p></div><h2>Active sources</h2><div class="sourceGrid"><?php foreach($sources as $s):?><a class="card sourceCard" href="/source.php?id=<?=h($s['public_id'])?>"><div class="meta"><?=h($s['domain'])?> <?php if($s['status']!=='current'):?><span class="badge warn"><?=h(ucfirst($s['status']))?></span><?php endif?></div><h3><?=h($s['title']?:$s['canonical_url'])?></h3><p><?=h((string)$s['annotation_count'])?> annotations · <?=h((string)$s['contributor_count'])?> contributors</p></a><?php endforeach?></div><h2>Recent annotations</h2><?php foreach($annotations as $a):?><article class="card"><div class="meta"><strong><?=h($a['display_name'])?></strong> @<?=h($a['username'])?> · <?=h($a['published_at'])?></div><h3><a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['title']?:$a['canonical_url'])?></a></h3><?php if($a['text_commentary']):?><p><?=nl2br(h($a['text_commentary']))?></p><?php endif?><?php if($a['selected_text']):?><blockquote><?=h($a['selected_text'])?></blockquote><?php endif?><?php if($a['audio_commentary_path']):?><audio class="wideAudio" controls src="<?=h(evidence_url($a['public_id'],'audio'))?>"></audio><?php if($a['transcript_text']):?><details><summary>Transcript</summary><p><?=nl2br(h($a['transcript_text']))?></p></details><?php endif?><?php endif?><a href="/annotation.php?id=<?=h($a['public_id'])?>">View annotation</a></article><?php endforeach?></section><aside><div class="card"><h3>Source-centered discovery</h3><p>Annotated organizes conversation around the original source rather than separating commentary from its evidence.</p></div></aside></main></body></html>
